    def event(self, name: str, agent: str | None = None, **metadata) -> None:
        """Record safe scalar metadata. Unknown fields and structured values are discarded."""
        agent = _identifier(agent if agent is not None else who())
        job = _identifier(JOB.get())
        safe = {}
        for key, value in metadata.items():
            if key not in _EVENT_FIELDS or not isinstance(value, (str, int, float, bool, type(None))):
                continue
            if isinstance(value, float) and not math.isfinite(value):
                continue
            safe[key] = _identifier(value) if isinstance(value, str) else value
        name = re.sub(r"[^a-zA-Z0-9_.-]", "_", str(name))[:64]
        self._seq += 1
        row = {"seq": self._seq, "t": round(self.now(), 6), "run_id": self.run_id,
               "event": name, "agent": agent, "job": job, **safe}
        metrics = self._agent(agent)
        if job != "-":
            metrics["jobs"].add(job)
        if name == "agent.start":
            metrics["starts"] += 1
        elif name == "agent.end":
            metrics["ends"] += 1
        if name in ("agent.start", "agent.end"):
            metrics["last_status"] = safe.get("status", name.split(".")[-1])
            metrics["phase"] = safe.get("phase", metrics["phase"])
        if len(self.events) < self.max_events:
            self.events.append(row)
        if self._events_path is not None:
            try:
                with self._events_path.open("a", encoding="utf-8") as stream:
                    stream.write(json.dumps(row, allow_nan=False) + "\n")
            except OSError:
                self._events_path = None
                log.warning("Efficiency event output unavailable")

    def record_model(self, model: str, usage=None, status: str = "success", started: float | None = None,
                     agent: str | None = None, attempt: int = 1) -> None:
        """One terminal record per actual provider attempt, including failed/cancelled retries."""
        if status not in ("success", "failure", "cancelled"):
            raise ValueError("model status must be success, failure or cancelled")
        agent = _identifier(agent if agent is not None else who())
        model = _identifier(model)
        tokens = token_usage(usage)
        ended = self.now()
        duration = max(0.0, ended - started) if started is not None else 0.0
        for metrics in (self._agent(agent)["models"].setdefault(model, _model_metrics()),
                        self._models.setdefault(model, _model_metrics())):
            metrics["calls"] += 1
            metrics[status] += 1
            metrics["seconds"] += duration
            for key in ("prompt_tokens", "cached_prompt_tokens", "completion_tokens", "usage_known"):
                metrics[key] += tokens[key]
        if started is not None:
            self.add("model.call", model, started, ended, agent)
        self.event("model.attempt", agent=agent, model=model, status=status, attempt=attempt,
                   started=round(started, 6) if started is not None else None, ended=round(ended, 6),
                   duration_s=round(duration, 6), **tokens)

    def record_evidence(self, author: str, site: str, kind: str, new: bool) -> None:
        metrics = self._agent(author)
        key = "new" if new else "duplicate"
        metrics["evidence_" + key] += 1
        by_site = metrics["evidence_by_site"].setdefault(_identifier(site), {"new": 0, "duplicate": 0})
        by_site[key] += 1
        self.event("evidence.post", agent=author, site=site, kind=kind, new=bool(new))

    def record_memory_query(self, consumer: str, producer: str, count: int = 1, site: str = "") -> None:
        """A producer batch returned by a query; consumption counts are accesses, not unique evidence."""
        count = max(0, int(count))
        consumer, producer, site = map(_identifier, (consumer, producer, site))
        metrics = self._agent(consumer)
        metrics["memory_queries"] += 1
        metrics["memory_items"] += count
        shared = consumer != producer and producer != "-"
        if shared:
            metrics["shared_items"] += count
            self._agent(producer)["contributions_consumed"] += count
            self._collaboration[(producer, consumer, site)] += count
        self.event("memory.query", agent=consumer, consumer=consumer, producer=producer, site=site,
                   count=count, shared=shared)

    def now(self) -> float:
        return time.monotonic() - self.start

    def add(self, category: str, label: str = "", start: float | None = None, end: float | None = None,
            agent: str | None = None) -> None:
        end = self.now() if end is None else end
        agent = _identifier(agent if agent is not None else who())
        start = end if start is None else start
        metrics = self._agent(agent)["span_seconds"]
        metrics[category] = metrics.get(category, 0.0) + max(0.0, end - start)
        if len(self.spans) < self.max_spans:
            self.spans.append((category, agent, str(label)[:80], start, end))
        self.event("span", agent=agent, category=category, started=round(start, 6), ended=round(end, 6),
                   duration_s=round(max(0.0, end - start), 6))

    @contextlib.contextmanager
    def span(self, category: str, label: str = "", agent: str | None = None):
        start = self.now()
        agent = who() if agent is None else agent
        try:
            yield
        finally:
            self.add(category, label, start, self.now(), agent)

    def mark(self, name: str, **info) -> bool:
        """Record a milestone once (its first time); True if this call recorded it."""
        if name in self.milestones:
            return False
        self.milestones[name] = (self.now(), info)
        log.info("milestone %s at %s %s", name, clock(self.now()), json.dumps(info, default=str)[:200] if info else "")
        return True

    def count(self, name: str, n: int = 1) -> None:
        self.counters[name] += n

    # ---- reports --------------------------------------------------------------------------------------------------
    def efficiency_report(self) -> dict:
        """Independent snapshot: work/time/token proxies cannot establish bid correctness."""
        def model_report(metrics):
            return {**metrics, "seconds": round(metrics["seconds"], 6),
                    "mean_latency_seconds": round(metrics["seconds"] / metrics["calls"], 6) if metrics["calls"] else None,
                    "uncached_prompt_tokens": metrics["prompt_tokens"] - metrics["cached_prompt_tokens"],
                    "total_tokens": metrics["prompt_tokens"] + metrics["completion_tokens"],
                    "usage_unknown": metrics["calls"] - metrics["usage_known"]}

        agents = {}
        for name, raw in sorted(self._agents.items()):
            metrics = {k: v for k, v in raw.items() if k not in ("models", "jobs", "span_seconds", "evidence_by_site")}
            metrics["models"] = {m: model_report(v) for m, v in sorted(raw["models"].items())}
            metrics["jobs"] = sorted(raw["jobs"])
            metrics["span_seconds"] = {k: round(v, 6) for k, v in sorted(raw["span_seconds"].items())}
            metrics["evidence_by_site"] = {k: dict(v) for k, v in sorted(raw["evidence_by_site"].items())}
            metrics["model_seconds"] = round(sum(v["seconds"] for v in raw["models"].values()), 6)
            metrics["total_tokens"] = sum(v["prompt_tokens"] + v["completion_tokens"] for v in raw["models"].values())
            metrics["evidence_per_model_second"] = (round(raw["evidence_new"] / metrics["model_seconds"], 6)
                                                     if metrics["model_seconds"] else None)
            metrics["evidence_per_1k_tokens"] = (round(raw["evidence_new"] * 1000 / metrics["total_tokens"], 6)
                                                if metrics["total_tokens"] else None)
            agents[name] = metrics
        return {"schema_version": 1, "run_id": self.run_id, "elapsed_seconds": round(self.now(), 6),
                "events": self._seq, "events_retained": len(self.events), "spans_retained": len(self.spans),
                "agents": agents, "models": {m: model_report(v) for m, v in sorted(self._models.items())},
                "collaboration": [{"producer": p, "consumer": c, "site": s, "items": n}
                                  for (p, c, s), n in sorted(self._collaboration.items())],
                "limitations": ["New evidence is a deduplicated work proxy, not verified bid correctness.",
                                "Shared memory items count accesses, including repeated queries.",
                                "Provider usage missing on errors/cancellation is unknown, not zero billed tokens.",
                                "Span categories may overlap; summed worker/model time is not run wall time."]}

