"""Where a run's time goes: spans (useful work, waits, recovery, model queue, extraction) and milestones.

The platform keeps only the tail of a run's log, so the timeline logs compact lines: a progress line per minute during
collection, one line per milestone, and a short report at the end (category totals, slowest spans, repeated work, time
to first usable bid / complete positions / accepted submission). Locally the full span list is written to `.swarm/`.

    with timeline.span("wait.dep", "requirements"):      # who: the running agent (context variable)
        ...
    timeline.mark("first usable bid", positions=2)       # milestone, first occurrence only
    timeline.count("reads.repeat")                        # repeated work

Categories:
  browse.step     one browsing step (model reply + action + page state): the useful browser work
  model.queue     waiting for a free model slot (our concurrency limit)
  model.call      model latency (analysis, planning, guard; browsing steps contain their own call)
  extract         saved page -> facts (model extraction)
  wait.dep        an agent waiting for an upstream result
  recovery        browser checks, hung tabs, reattaching, retries after failures
  guard           popup sweeps before a step
  browse.failed   whole browses that ended without success (repeated later)
"""
import contextlib
import contextvars
import json
import logging
import math
import re
import time
from collections import defaultdict
from pathlib import Path

log = logging.getLogger("timeline")

AGENT: contextvars.ContextVar[str] = contextvars.ContextVar("swarm_agent", default="-")
JOB: contextvars.ContextVar[str] = contextvars.ContextVar("swarm_job", default="-")

# Only identifiers, classifications and numeric measurements belong in the efficiency stream.
# In particular, never add prompts, replies, URLs, page text, exceptions or credentials here.
_EVENT_FIELDS = frozenset({
    "site", "kind", "status", "phase", "role", "browser", "model", "author", "producer", "consumer",
    "count", "new", "attempt", "duration_s", "category", "started", "ended", "code", "reason",
    "prompt_tokens", "cached_prompt_tokens", "completion_tokens", "usage_known", "job_id", "evidence_id",
    "success", "step", "shared", "items", "timeout_s", "agents", "workers", "capacity",
})


def _identifier(value) -> str:
    """Opaque runtime identifiers only; bound their size and remove control characters."""
    return re.sub(r"[\x00-\x1f\x7f]", "", str(value))[:128]


def _usage_value(usage, name: str, default=None):
    return usage.get(name, default) if isinstance(usage, dict) else getattr(usage, name, default)


def token_usage(usage) -> dict:
    """Normalize OpenAI and browser-use usage; cached input is a subset of prompt input."""
    def number(value):
        try:
            return max(0, int(value or 0))
        except (TypeError, ValueError, OverflowError):
            return 0

    prompt = number(_usage_value(usage, "prompt_tokens", _usage_value(usage, "input_tokens", 0)))
    completion = number(_usage_value(usage, "completion_tokens", _usage_value(usage, "output_tokens", 0)))
    details = _usage_value(usage, "prompt_tokens_details", _usage_value(usage, "input_tokens_details", None))
    cached = number(_usage_value(details, "cached_tokens", _usage_value(
        usage, "prompt_cached_tokens", _usage_value(usage, "cached_prompt_tokens", 0))))
    return {"prompt_tokens": prompt, "cached_prompt_tokens": min(prompt, cached),
            "completion_tokens": completion, "usage_known": usage is not None}


def _model_metrics() -> dict:
    return {"calls": 0, "success": 0, "failure": 0, "cancelled": 0, "usage_known": 0,
            "prompt_tokens": 0, "cached_prompt_tokens": 0, "completion_tokens": 0, "seconds": 0.0}


def _agent_metrics() -> dict:
    return {"models": {}, "evidence_new": 0, "evidence_duplicate": 0, "evidence_by_site": {},
            "memory_queries": 0, "memory_items": 0, "shared_items": 0, "contributions_consumed": 0,
            "starts": 0, "ends": 0, "last_status": "", "phase": "", "jobs": set(), "span_seconds": {}}


def who() -> str:
    return AGENT.get()


class Timeline:
    def __init__(self, start: float | None = None):
        self.start = time.monotonic() if start is None else start
        self.spans: list[tuple[str, str, str, float, float]] = []   # category, agent, label, start, end (run clock)
        self.milestones: dict[str, tuple[float, dict]] = {}
        self.counters: dict[str, int] = defaultdict(int)
        self.max_spans = 20_000
        self.events: list[dict] = []
        self.max_events = 20_000
        self._seq = 0
        self._agents: dict[str, dict] = {}
        self._models: dict[str, dict] = {}
        self._collaboration: dict[tuple[str, str, str], int] = defaultdict(int)
        self.run_id = "local"
        self._events_path: Path | None = None

    def _agent(self, agent: str) -> dict:
        return self._agents.setdefault(_identifier(agent), _agent_metrics())

    def configure_output(self, directory: Path, run_id: str = "local") -> None:
        """Start this run's local JSONL stream. Existing files are replaced, never inspected."""
        self.run_id = _identifier(run_id)
        try:
            directory = Path(directory)
            directory.mkdir(parents=True, exist_ok=True)
            self._events_path = directory / "events.jsonl"
            with self._events_path.open("w", encoding="utf-8") as stream:
                for row in self.events:
                    stream.write(json.dumps({**row, "run_id": self.run_id}, allow_nan=False) + "\n")
        except OSError:
            self._events_path = None
            log.warning("Efficiency event output unavailable")

    def event(self, name: str, agent: str | None = None, **metadata) -> None:
        """Record safe scalar metadata. Unknown fields and structured values are discarded."""

